<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import type { AuditPreview } from '../../../../packages/contracts/src/audit';
import AuditJsonValue from './AuditJsonValue.vue';
import AuditTextValue from './AuditTextValue.vue';
import { auditSections, auditJsonSummary, parseAuditText } from './audit-preview-model';
const props=defineProps<{title:string;preview:AuditPreview|null|undefined}>();
const mode=ref<'structured'|'formatted'|'raw'>('structured');const copyStatus=ref('');const copying=ref(false);
const previewText=computed(()=>props.preview?.text??'');
const parsed=computed(()=>parseAuditText(previewText.value));
const sections=computed(()=>parsed.value.kind==='json'?auditSections(parsed.value.value):[]);
watch([previewText,()=>props.title],()=>{mode.value='structured';copyStatus.value='';});
function fallbackCopy(text:string):boolean {
  const previous=document.activeElement;const field=document.createElement('textarea');field.value=text;field.readOnly=true;field.style.position='fixed';field.style.left='-10000px';field.style.top='0';document.body.append(field);
  try{field.focus();field.select();return document.execCommand('copy');}finally{field.remove();if(previous instanceof HTMLElement)previous.focus({preventScroll:true});}
}
async function copyPreview():Promise<void>{
  if(!props.preview||copying.value)return;const text=props.preview.text;copying.value=true;copyStatus.value='';
  try{let copied=false;try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);copied=true;}}catch{/* HTTP dashboards can use the user-triggered local copy fallback. */}
    if(!copied)copied=fallbackCopy(text);if(props.preview?.text!==text)return;copyStatus.value=copied?'已复制脱敏预览。内容与原始预览一致。':'复制失败。请切换到原始预览，手动选择并复制。';
  }catch{copyStatus.value='复制失败。请切换到原始预览，手动选择并复制。';}finally{copying.value=false;}
}
</script>
<template><section class="audit-preview" :aria-label="title"><header class="audit-preview-header"><h4>{{title}}</h4><button v-if="preview" type="button" :disabled="copying" @click="copyPreview">{{copying?'正在复制…':'复制脱敏预览'}}</button></header><template v-if="preview"><div class="audit-preview-meta"><span>原始记录 {{preview.originalChars.toLocaleString('zh-CN')}} 字符</span><span>当前预览 {{preview.text.length.toLocaleString('zh-CN')}} 字符</span><strong v-if="preview.truncated">已截断</strong><strong v-if="preview.redacted">已脱敏</strong></div><p v-if="preview.truncated" class="audit-preview-note">仅显示已保存的部分内容。切换视图或复制不会恢复省略的原文。</p><div v-if="parsed.kind==='json'" class="audit-view-switch" role="group" :aria-label="`${title}显示方式`"><button type="button" :aria-pressed="mode==='structured'" @click="mode='structured'">结构化</button><button type="button" :aria-pressed="mode==='formatted'" @click="mode='formatted'">格式化 JSON</button><button type="button" :aria-pressed="mode==='raw'" @click="mode='raw'">原始预览</button></div><p v-if="copyStatus" class="audit-preview-note" role="status">{{copyStatus}}</p>
  <div v-if="parsed.kind==='json'&&mode==='structured'" class="audit-structured"><template v-for="(section,sectionIndex) in sections" :key="sectionIndex"><section v-if="section.kind==='messages'" class="audit-message-section"><h5>{{section.title}} <span>{{section.cards.length}} 条</span></h5><article v-for="(card,cardIndex) in section.cards" :key="cardIndex" class="audit-message-card"><header><span class="audit-card-number">{{String(cardIndex+1).padStart(2,'0')}}</span><strong>{{card.title}}</strong></header><p v-if="card.metadata.length" class="audit-card-metadata">{{card.metadata.join(' · ')}}</p><div class="audit-message-blocks"><template v-for="(block,blockIndex) in card.blocks" :key="blockIndex"><AuditTextValue v-if="block.kind==='text'" :text="block.text"/><details v-else-if="block.collapsed" class="audit-data-section"><summary>{{block.label}}</summary><AuditJsonValue :value="block.value"/></details><section v-else class="audit-data-block"><h6>{{block.label}}</h6><AuditJsonValue :value="block.value"/></section></template></div><details v-if="card.extra" class="audit-data-section audit-message-extra"><summary>其他消息字段</summary><AuditJsonValue :value="card.extra"/></details></article><p v-if="!section.cards.length" class="audit-preview-note">（没有消息）</p></section><details v-else-if="section.collapsed" class="audit-data-section audit-top-section"><summary><strong>{{section.title}}</strong><span>{{auditJsonSummary(section.value)}}</span></summary><AuditJsonValue :value="section.value"/></details><section v-else class="audit-top-section"><h5>{{section.title}}</h5><AuditJsonValue :value="section.value"/></section></template></div>
  <div v-else-if="parsed.kind==='json'&&mode==='formatted'" class="audit-code-preview"><AuditTextValue :text="parsed.formatted" monospace expanded-by-default/></div><div v-else class="audit-code-preview"><p v-if="parsed.kind==='text'&&parsed.incompleteJson" class="audit-preview-note">此预览不是完整 JSON。按保存的文本显示。</p><p v-if="parsed.kind==='text'&&parsed.structureUnavailable" class="audit-preview-note">此 JSON 的层级过深。按保存的文本显示。</p><AuditTextValue expanded-by-default :text="preview.text" :monospace="parsed.kind==='json'||parsed.incompleteJson"/></div>
</template><p v-else class="audit-preview-note">没有保存此项预览。</p></section></template>
<style scoped>.audit-preview{display:grid;gap:10px;min-width:0}.audit-preview-header{display:flex;align-items:center;justify-content:space-between;gap:12px}.audit-preview h4{font-size:13px;margin:0}.audit-preview-header>button{font-size:11px;padding:5px 9px;flex-shrink:0;background:var(--surface)}.audit-preview-meta{display:flex;flex-wrap:wrap;gap:6px 12px;color:var(--muted);font-size:10px}.audit-preview-meta>strong{font-weight:500;color:var(--accent-ink);background:var(--accent-soft);padding:1px 6px;border-radius:4px}.audit-preview-note{margin:0;color:var(--muted);font-size:11px;line-height:1.8}.audit-view-switch{display:flex;flex-wrap:wrap;gap:5px}.audit-view-switch>button{font-size:11px;padding:5px 10px;background:transparent;border-color:var(--line);color:var(--muted)}.audit-view-switch>button[aria-pressed=true]{background:var(--accent-soft);border-color:var(--accent);color:var(--accent-ink)}.audit-structured{display:grid;gap:15px;border:1px solid var(--line);border-radius:7px;padding:15px;background:var(--surface-soft);min-width:0}.audit-top-section{min-width:0}.audit-top-section>h5,.audit-message-section>h5{margin:0 0 10px;font-size:12px;font-weight:600}.audit-message-section>h5>span{margin-left:7px;font-size:10px;font-weight:400;color:var(--muted)}.audit-data-section>summary{cursor:pointer;font-size:11px;line-height:1.7;color:var(--muted);padding:4px 0}.audit-top-section>summary{display:flex;align-items:baseline;flex-wrap:wrap;gap:10px}.audit-top-section>summary::before{content:'▸'}.audit-top-section[open]>summary::before{content:'▾'}.audit-top-section>summary>strong{color:var(--ink);font-size:12px}.audit-data-section[open]>summary{margin-bottom:8px}.audit-message-section{min-width:0}.audit-message-card{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:13px;margin-top:9px;min-width:0}.audit-message-card>header{display:flex;gap:9px;align-items:baseline}.audit-message-card>header>strong{font-size:12px;overflow-wrap:anywhere}.audit-card-number{color:var(--accent-ink);font-size:10px;font-variant-numeric:tabular-nums}.audit-card-metadata{margin:6px 0;color:var(--muted);font-size:10px;overflow-wrap:anywhere;line-height:1.7}.audit-message-blocks{display:grid;gap:12px;margin-top:11px;min-width:0}.audit-data-block h6{margin:0 0 6px;color:var(--muted);font-size:11px;font-weight:500}.audit-message-extra{margin-top:10px;border-top:1px solid var(--line);padding-top:7px}.audit-code-preview{background:var(--surface-soft);border:1px solid var(--line);border-radius:6px;padding:13px;display:grid;gap:8px;min-width:0}@media(max-width:600px){.audit-preview-header{align-items:flex-start;flex-wrap:wrap}.audit-structured{padding:10px}.audit-message-card{padding:10px}.audit-preview-meta{gap:6px 9px}}</style>
